"""Self-update from GitHub releases: download the tagged source and run its install.sh."""
import json
import re
import shutil
import subprocess
import tarfile
import tempfile
import urllib.request
from pathlib import Path

from .version import REPO, VERSION


def _get(url):
    req = urllib.request.Request(url, headers={"User-Agent": "fbt-calibrator"})
    return urllib.request.urlopen(req, timeout=20)


def newer(a, b):
    num = lambda s: [int(x) for x in re.findall(r"\d+", s)]
    return num(a) > num(b)


def check():
    """The latest release if it is newer than this one, else None."""
    with _get(f"https://api.github.com/repos/{REPO}/releases/latest") as r:
        rel = json.load(r)
    tag = rel.get("tag_name", "")
    if tag and newer(tag, VERSION):
        return {"tag": tag, "version": tag.lstrip("v")}
    return None


def install(info):
    with tempfile.TemporaryDirectory() as tmp:
        archive = Path(tmp) / "src.tar.gz"
        with _get(f"https://codeload.github.com/{REPO}/tar.gz/refs/tags/{info['tag']}") as r, \
                open(archive, "wb") as out:
            shutil.copyfileobj(r, out)
        with tarfile.open(archive) as t:
            t.extractall(tmp, filter="data")
        src = next(p for p in Path(tmp).iterdir() if p.is_dir())
        res = subprocess.run(["bash", str(src / "install.sh"), "--no-restart"],
                             capture_output=True, text=True)
        if res.returncode:
            raise RuntimeError((res.stderr or res.stdout).strip()[-400:])
